from pathlib import Path
from datetime import datetime
import csv

import matplotlib
matplotlib.use("Agg")  # headless backend (saves to file)
import matplotlib.pyplot as plt

from ultralytics import YOLO

# ============================================================
# SETTINGS
# ============================================================

# Path to the YOLO dataset (generated by prepare_yolo_dataset.py)
DATA_YAML = Path(
    "dataset_yolo/data.yaml"
)

# Folder where training results will be saved
PROJECT_DIR = Path(
    "runs_comparacao"
)

# Models to compare: the 3 most recent stable YOLO versions on Ultralytics (YOLOv8, YOLO11 and YOLO26)
# Small (s) variant: best balance for small and imbalanced datasets
MODELS = {
    "yolov8s": "yolov8s.pt",
    "yolo11s": "yolo11s.pt",
    "yolo26s": "yolo26s.pt",
}

# ------------------------------------------------------------
# BASIC TRAINING PARAMETERS
# (identical across all models for a fair comparison)
# ------------------------------------------------------------

EPOCHS = 300
IMG_SIZE = 640
BATCH = 16
PATIENCE = 20          # early stopping
SEED = 42
DEVICE = 0             # 0 = first GPU | "cpu" = no GPU


# ============================================================
# TRAINING + VALIDATION
# ============================================================

def train(name, weights):

    print("\n" + "=" * 60)
    print(f"TRAINING: {name}")
    print("=" * 60)

    model = YOLO(weights)

    model.train(
        data=str(DATA_YAML),
        epochs=EPOCHS,
        imgsz=IMG_SIZE,
        batch=BATCH,
        patience=PATIENCE,
        seed=SEED,
        device=DEVICE,
        project=str(PROJECT_DIR),
        name=name,
        exist_ok=True,
    )

    # Evaluation on the test set
    metrics = model.val(
        data=str(DATA_YAML),
        split="test",
        imgsz=IMG_SIZE,
        batch=BATCH,
        device=DEVICE,
        project=str(PROJECT_DIR),
        name=f"{name}_test",
        exist_ok=True,
    )

    return {
        "model": name,
        "mAP50": round(float(metrics.box.map50), 4),
        "mAP50-95": round(float(metrics.box.map), 4),
        "precision": round(float(metrics.box.mp), 4),
        "recall": round(float(metrics.box.mr), 4),
    }


# ============================================================
# TABLES (CSV + MARKDOWN)
# ============================================================

METRICS = ["mAP50", "mAP50-95", "precision", "recall"]


def save_csv(results, csv_path):

    with open(csv_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(
            f,
            fieldnames=["model"] + METRICS,
        )
        writer.writeheader()
        writer.writerows(results)


def save_markdown(results, md_path):

    lines = []
    lines.append("# YOLO Models Comparison (test set)")
    lines.append("")
    lines.append(
        "| Model | " + " | ".join(METRICS) + " |"
    )
    lines.append(
        "|" + "---|" * (len(METRICS) + 1)
    )

    for r in results:
        values = " | ".join(
            f"{r[m]:.4f}" for m in METRICS
        )
        lines.append(f"| {r['model']} | {values} |")

    md_path.write_text("\n".join(lines) + "\n", encoding="utf-8")


# ============================================================
# COMPARISON CHARTS
# ============================================================

def generate_charts(results, out_dir):

    models = [r["model"] for r in results]
    colors = ["#4C72B0", "#DD8452", "#55A868"]

    # --------------------------------------------------------
    # 1) One bar chart per metric
    # --------------------------------------------------------

    fig, axes = plt.subplots(2, 2, figsize=(12, 9))
    axes = axes.flatten()

    for idx, metric in enumerate(METRICS):

        ax = axes[idx]
        values = [r[metric] for r in results]

        bars = ax.bar(
            models,
            values,
            color=colors[: len(models)],
        )

        ax.set_title(metric, fontsize=13, fontweight="bold")
        ax.set_ylim(0, 1)
        ax.grid(axis="y", linestyle="--", alpha=0.4)

        # value on top of each bar
        for bar, value in zip(bars, values):
            ax.text(
                bar.get_x() + bar.get_width() / 2,
                value + 0.01,
                f"{value:.3f}",
                ha="center",
                va="bottom",
                fontsize=10,
            )

    fig.suptitle(
        "Metric comparison per model (test)",
        fontsize=15,
        fontweight="bold",
    )
    fig.tight_layout(rect=(0, 0, 1, 0.97))

    path_bars = out_dir / "comparacao_metricas.png"
    fig.savefig(path_bars, dpi=150)
    plt.close(fig)

    # --------------------------------------------------------
    # 2) Grouped bar chart (all metrics together)
    # --------------------------------------------------------

    fig, ax = plt.subplots(figsize=(11, 6))

    n_metrics = len(METRICS)
    width = 0.8 / len(models)

    base_positions = range(n_metrics)

    for i, r in enumerate(results):

        values = [r[m] for m in METRICS]
        offset = (
            i * width
            - (len(models) - 1) * width / 2
        )
        positions = [p + offset for p in base_positions]

        bars = ax.bar(
            positions,
            values,
            width=width,
            label=r["model"],
            color=colors[i % len(colors)],
        )

        for bar, value in zip(bars, values):
            ax.text(
                bar.get_x() + bar.get_width() / 2,
                value + 0.01,
                f"{value:.3f}",
                ha="center",
                va="bottom",
                fontsize=8,
            )

    ax.set_xticks(list(base_positions))
    ax.set_xticklabels(METRICS)
    ax.set_ylim(0, 1)
    ax.set_ylabel("Value")
    ax.set_title(
        "Comparison between models (grouped bars)",
        fontsize=14,
        fontweight="bold",
    )
    ax.grid(axis="y", linestyle="--", alpha=0.4)
    ax.legend(title="Model")

    fig.tight_layout()

    path_grouped = out_dir / "comparacao_agrupada.png"
    fig.savefig(path_grouped, dpi=150)
    plt.close(fig)

    return [path_bars, path_grouped]


# ============================================================
# EXECUTION
# ============================================================

def main():

    if not DATA_YAML.exists():
        raise FileNotFoundError(
            f"data.yaml not found: {DATA_YAML}\n"
            "Run prepare_yolo_dataset.py first."
        )

    PROJECT_DIR.mkdir(parents=True, exist_ok=True)

    results = []

    for name, weights in MODELS.items():
        result = train(name, weights)
        results.append(result)

    # --------------------------------------------------------
    # COMPARISON TABLE
    # --------------------------------------------------------

    print("\n" + "=" * 60)
    print("FINAL COMPARISON (test set)")
    print("=" * 60)

    header = (
        f"{'Model':<12}"
        f"{'mAP50':>10}"
        f"{'mAP50-95':>12}"
        f"{'Precision':>12}"
        f"{'Recall':>10}"
    )

    print(header)
    print("-" * 60)

    for r in results:
        print(
            f"{r['model']:<12}"
            f"{r['mAP50']:>10}"
            f"{r['mAP50-95']:>12}"
            f"{r['precision']:>12}"
            f"{r['recall']:>10}"
        )

    # --------------------------------------------------------
    # SAVE TABLES (CSV + MARKDOWN) AND CHARTS
    # --------------------------------------------------------

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    out_dir = PROJECT_DIR / f"comparacao_{timestamp}"
    out_dir.mkdir(parents=True, exist_ok=True)

    csv_path = out_dir / "metricas.csv"
    md_path = out_dir / "metricas.md"

    save_csv(results, csv_path)
    save_markdown(results, md_path)

    charts = generate_charts(results, out_dir)

    print("\n" + "=" * 60)
    print("GENERATED FILES")
    print("=" * 60)
    print(f"CSV table:      {csv_path}")
    print(f"Markdown table: {md_path}")
    for c in charts:
        print(f"Chart:          {c}")
    print(f"\nRuns saved at: {PROJECT_DIR}")
    print("=" * 60)


if __name__ == "__main__":
    main()
